using System;\nusing RestSharp;\nusing Newtonsoft.Json;\nusing Serilog;\n\nnamespace AutomationFramework.API.BusinessLogic\n{\n    public class PetStoreApiHelper\n    {\n        private readonly RestClient _client;\n\n        public PetStoreApiHelper(string baseUrl)\n        {\n            _client = new RestClient(baseUrl);\n        }\n\n        public RestResponse SendGetRequest(string endpoint)\n        {\n            try\n            {\n                var request = new RestRequest(endpoint, Method.Get);\n                Log.Information(\"Sending GET request to {Endpoint}\", endpoint);\n                var response = _client.Execute(request);\n                Log.Information(\"Received response: {StatusCode}\", response.StatusCode);\n                return response;\n            }\n            catch (Exception ex)\n            {\n                Log.Error(ex, \"Error occurred while sending GET request\");\n                throw;\n            }\n        }\n\n        public RestResponse SendPostRequest(string endpoint, object body)\n        {\n            try\n            {\n                var request = new RestRequest(endpoint, Method.Post);\n                request.AddJsonBody(body);\n                Log.Information(\"Sending POST request to {Endpoint} with body: {Body}\", endpoint, JsonConvert.SerializeObject(body));\n                var response = _client.Execute(request);\n                Log.Information(\"Received response: {StatusCode}\", response.StatusCode);\n                return response;\n            }\n            catch (Exception ex)\n            {\n                Log.Error(ex, \"Error occurred while sending POST request\");\n                throw;\n            }\n        }\n\n        public RestResponse SendPutRequest(string endpoint, object body)\n        {\n            try\n            {\n                var request = new RestRequest(endpoint, Method.Put);\n                request.AddJsonBody(body);\n                Log.Information(\"Sending PUT request to {Endpoint} with body: {Body}\", endpoint, JsonConvert.SerializeObject(body));\n                var response = _client.Execute(request);\n                Log.Information(\"Received response: {StatusCode}\", response.StatusCode);\n                return response;\n            }\n            catch (Exception ex)\n            {\n                Log.Error(ex, \"Error occurred while sending PUT request\");\n                throw;\n            }\n        }\n\n        public RestResponse SendDeleteRequest(string endpoint)\n        {\n            try\n            {\n                var request = new RestRequest(endpoint, Method.Delete);\n                Log.Information(\"Sending DELETE request to {Endpoint}\", endpoint);\n                var response = _client.Execute(request);\n                Log.Information(\"Received response: {StatusCode}\", response.StatusCode);\n                return response;\n            }\n            catch (Exception ex)\n            {\n                Log.Error(ex, \"Error occurred while sending DELETE request\");\n                throw;\n            }\n        }\n    }\n}